CREATE TABLE `concept` (
  `dharma` int(11) NOT NULL,
  `nama` varchar(255) NOT NULL COMMENT 'ярлык для ориентации',
  `defin` varchar(1000) DEFAULT NULL COMMENT 'кэш дефиниции: род + свойства + виды',
  `vol_zero` tinyint(4) DEFAULT NULL,
  `vol_ed` tinyint(4) DEFAULT NULL,
  `vol_countable` tinyint(4) DEFAULT NULL,
  `vol_sobir` tinyint(4) DEFAULT NULL,
  `vol_sootn` tinyint(4) DEFAULT NULL,
  `cont_konkr` tinyint(4) DEFAULT NULL,
  `cont_abs` tinyint(4) DEFAULT NULL,
  `cont_opred` tinyint(4) DEFAULT NULL,
  `cont_empir` tinyint(4) DEFAULT NULL,
  `universum_id` int(11) NOT NULL DEFAULT '1',
  `processed` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`dharma`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
