(3776,1803,'83',1290,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:10'),(3777,1804,'72',1805,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:10'),(3778,1804,'61',1805,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:10'),(3779,1801,'61',1806,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:10'),(3780,1801,'83',103,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:10'),(3781,1802,'83',103,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:10'),(3782,1806,'61',2095,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:11'),(3783,1816,'63',2098,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:11'),(3784,1815,'61',1816,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:11'),(3785,216,'61',217,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:11'),(3786,1814,'72',1813,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:11'),(3787,1816,'72',1813,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:11'),(3788,217,'61',1814,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:12'),(3789,1813,'70',19,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:12'),(3790,1815,'61',1818,1,NULL,'ok','llm:fill:self',NULL,'2026-08-28 15:35:12');
